#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ====================================================================
 *  轮到你了：模块 01  typedef
 *  作用：字符串就是字符数组，KMP 只需要两个东西：模式串和它的 match 表。
 *  提示：先写函数签名，再写循环定位，最后写指针操作。
 *  写完按 Ctrl + Enter 编译运行，点"对比"看与参考实现的差异。
 * ==================================================================== */



/* ======== 测试驱动（已给出，可自行修改） ======== */
/* 验证类型与约定（只用本模块的东西：类型、宏、样例模式串） */
int main(void)
{
    const char *P = KMP_DEMO_PATTERN;
    MatchTable match = KMP_DEMO_MATCH;
    int j;

    printf("模式串 P = \"%s\"（长度 %d）\n", P, (int)strlen(P));
    printf("类型 MatchTable 的大小 = %d 个 int\n\n", (int)(sizeof(MatchTable) / sizeof(int)));

    printf("按 match 的定义逐个看 P 的每个前缀：\n");
    for (j = 0; j < KMP_DEMO_LEN; j++)
    {
        printf("  P[0..%d] = %.*s  →  match[%d] = %d\n",
               j, j + 1, P, j, match[j]);
    }

    printf("\n怎么读这张表：\n");
    printf("  match[3] = 2 表示 \"abab\" 的最长相等前后缀是 \"ab\"（长度 2）\n");
    printf("  match[0] = 0 是递推起点：长度为 1 的串没有真前后缀\n");
    printf("  整张表只取决于 P，和主串 S 无关\n");
    printf("  找不到时统一返回 KMP_NOTFOUND（= %d）\n", KMP_NOTFOUND);

    return 0;
}

modes.detail:
// ============ 先写下"笨办法"，才有比较的对象 ============
//
// 算法课上一个常见的坏习惯：只讲最优解，不讲它到底优化了什么。
// 这一模块故意把 O(n·m) 的写法放在最前面，因为**KMP 的每一行都是为了
// 消掉这里的某一次重复比较**。
//
// 两层循环的语义：
//
//     for (i = 0; i + m <= n; i++)     ← 主串的每个起手位置都试一遍
//         for (j = 0; j < m && S[i+j] == P[j]; j++)   ← 从这儿往后逐字符比
//
// 内层 while 退出时有两种情况：
//
//     j == m    比完了整个模式串 → 在 i 处匹配成功
//     S[i+j] != P[j]             → 这个起手位置失败，换下一个 i
//
// ============ 复杂度到底差多少 ============
//
// 最好情况：第一个字符就不匹配，每次只比 1 次 → O(n)
// 最坏情况：S = "aaaa...a"、P = "aaab" → 每个位置都要比 m 次 → O(n·m)
//
// n = 100 万、m = 1000 时，最坏要 10 亿次比较 —— 这就是要 KMP 的理由。
// 而且注意：KMP 的 O(n+m) 是**最坏情况**的保证，不是"平均情况"。

// 暴力匹配：从每个位置起手，逐字符比
// 返回第一次匹配的下标，找不到返回 -1
// 最坏 O(n*m)：主串指针会退回去重比
// S = "aaaaaab"、P = "aaab" 就是最坏情况
int NaiveMatch(const char *S, const char *P)
{
// m 是模式串长度，n 是主串长度
    int n = (int)strlen(S);
    int m = (int)strlen(P);
    int i, j;

// 空模式串约定：在任何位置都算匹配，返回 0
    if (m == 0) return 0;
// 模式串比主串还长，不可能匹配
    if (n < m) return -1;

// 主串的每个起手位置都试一遍；i + m > n 时后面长度不够，不必再试
    for (i = 0; i + m <= n; i++)
    {
// 从 i 开始逐个字符比，遇到不同就跳出
        for (j = 0; j < m && S[i + j] == P[j]; j++)
        {
// 空循环体：比较和推进都在 for 的头部完成了
        }
// j 走到 m 说明整个模式串都比中了
        if (j == m) return i;
// 否则这个 i 失败 —— 主串指针退回到 i+1，前面比过的字符全部作废
    }

// 所有起手位置都试过还没中，说明主串里没有这个模式串
    return -1;
}

