/* 验证暴力匹配：先在一个正常场景里找对位置，再看找不到的情况 */
int main(void)
{
    const char *tests[3][2] = {
        { "abababab", "abab" },
        { "xxababacxx", "ababac" },
        { "abcdef", "xyz" },
    };
    int t;

    for (t = 0; t < 3; t++)
