    if (m == 0) return;

    match[0] = 0;

    for (j = 1; j < m; j++)
    {
        k = match[j - 1];

        while (k > 0 && P[j] != P[k])
        {
            k = match[k - 1];
        }

        if (P[j] == P[k])
        {
            match[j] = k + 1;
        }
        else
        {
            match[j] = 0;
        }
    }
}

/* ======== [已给出] 模块 05 KMPMatch ======== */

int KMPMatch(const char *S, const char *P, const int *match)
{
    int n = (int)strlen(S);
    int m = (int)strlen(P);
    int i = 0;
    int j = 0;

    if (m == 0) return 0;
    if (match == NULL) return -1;

    while (i < n && j < m)
    {
        if (S[i] == P[j])
        {
            i++;
            j++;
        }
        else if (j > 0)
        {
            j = match[j - 1];
        }
        else
        {
            i++;
        }
    }

    return (j == m) ? (i - m) : -1;
}

/* ====================================================================
 *  轮到你了：模块 06  main
 *  作用：同一组数据分别跑两个算法，对照匹配位置与比较次数。
 *  提示：先写函数签名，再写循环定位，最后写指针操作。
 *  写完按 Ctrl + Enter 编译运行，点"对比"看与参考实现的差异。
 * ==================================================================== */

modes.detail:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// ============ 为什么 KMP 的接口这么简单 ============
//
// 暴力匹配需要"主串 + 模式串 + 两个下标 + 两层循环"，参数一堆。
// KMP 把它压到只剩两样：
//
//     S        主串（只读，指针永不后退）
//     P        模式串（只读）
//     match    P 的"最长相等前后缀"表，长度和 P 一样
//
// 注意 match 表是**模式串自己的性质**，和主串无关 ——
// 所以同一个模式串在多个主串里查找时，这张表只需要算一次。
// 这是 KMP 能工程化的关键：把"预处理模式串"和"扫描主串"分成两步。
//
// ============ 下标从 0 开始 ============
//
// 教材里 KMP 的 next 数组常常从 1 开始（next[1] = 0），那是为了配合
// "字符串从下标 1 存"的写法。这里统一用 C 的习惯 **从 0 开始**：
//
//     P         a  b  a  b  a  c
//     下标      0  1  2  3  4  5
//     match     0  0  1  2  3  0
//
// match[0] 永远是 0（长度为 1 的串没有真前后缀），这是递推的起点。

// 下标统一从 0 开始，和 C 的习惯一致
// match[j] = P[0..j] 的最长相等前后缀长度（"真"前后缀，不含整个串本身）
// 例子：P = "ababaca" 时 match = { 0, 0, 1, 2, 3, 0, 1 }

// ============ match 表用什么类型装 ============
//
// MatchTable 是"整型数组"的类型别名，长度由调用者保证（至少 strlen(P)）
// 用 typedef 而不是裸 int*，是为了让函数签名自解释：
//     void buildMatch(const char *P, MatchTable match)
// 一眼能看出第二个参数是"存 match 表的数组"，而不是随便一个 int 指针
typedef int MatchTable[64];

// 和前面几节一样，用宏定义状态码，让函数返回值有意义
// 找不到时的返回值，比裸写 -1 好读
#define KMP_NOTFOUND (-1)

// ============ 一份可以直接对照的样例 ============
//
// 后面几个模块都用这个模式串举例，省得每次重写：
//
//     P         a  b  a  b  a  c
//     下标      0  1  2  3  4  5
//     match     0  0  1  2  3  0
// 示例模式串：a b a b a c
#define KMP_DEMO_PATTERN "ababac"
// 它的 match 表（手算结果，用来给 buildMatch 对答案）
#define KMP_DEMO_MATCH { 0, 0, 1, 2, 3, 0 }
// 示例模式串的长度
#define KMP_DEMO_LEN 6

// ============ 先写下"笨办法"，才有比较的对象 ============
//
// 算法课上一个常见的坏习惯：只讲最优解，不讲它到底优化了什么。
// 这一模块故意把 O(n·m) 的写法放在最前面，因为**KMP 的每一行都是为了
// 消掉这里的某一次重复比较**。
//
// 两层循环的语义：
//
//     for (i = 0; i + m <= n; i++)     ← 主串的每个起手位置都试一遍
//         for (j = 0; j < m && S[i+j] == P[j]; j++)   ← 从这儿往后逐字符比
//
// 内层 while 退出时有两种情况：
//
//     j == m    比完了整个模式串 → 在 i 处匹配成功
//     S[i+j] != P[j]             → 这个起手位置失败，换下一个 i
//
// ============ 复杂度到底差多少 ============
//
// 最好情况：第一个字符就不匹配，每次只比 1 次 → O(n)
// 最坏情况：S = "aaaa...a"、P = "aaab" → 每个位置都要比 m 次 → O(n·m)
//
// n = 100 万、m = 1000 时，最坏要 10 亿次比较 —— 这就是要 KMP 的理由。
// 而且注意：KMP 的 O(n+m) 是**最坏情况**的保证，不是"平均情况"。

// 暴力匹配：从每个位置起手，逐字符比
// 返回第一次匹配的下标，找不到返回 -1
// 最坏 O(n*m)：主串指针会退回去重比
// S = "aaaaaab"、P = "aaab" 就是最坏情况
int NaiveMatch(const char *S, const char *P)
{
// m 是模式串长度，n 是主串长度
    int n = (int)strlen(S);
    int m = (int)strlen(P);
    int i, j;

// 空模式串约定：在任何位置都算匹配，返回 0
    if (m == 0) return 0;
// 模式串比主串还长，不可能匹配
    if (n < m) return -1;

// 主串的每个起手位置都试一遍；i + m > n 时后面长度不够，不必再试
    for (i = 0; i + m <= n; i++)
    {
// 从 i 开始逐个字符比，遇到不同就跳出
        for (j = 0; j < m && S[i + j] == P[j]; j++)
        {
// 空循环体：比较和推进都在 for 的头部完成了
        }
// j 走到 m 说明整个模式串都比中了
        if (j == m) return i;
// 否则这个 i 失败 —— 主串指针退回到 i+1，前面比过的字符全部作废
    }

// 所有起手位置都试过还没中，说明主串里没有这个模式串
    return -1;
}

// ============ 先搞清楚"前后缀"是什么 ============
//
// 对串 P[0..j]，**前缀**是从头开始的连续一段，**后缀**是到结尾的连续一段。
// 我们要的是"相等的前缀和后缀里最长的那一对"的长度。
//
// 注意两个限定：
//   1. "真"前后缀 —— 前后缀不能是整个串本身（否则长度永远是 j+1，没信息）
//   2. 只看长度，不用关心是哪一段（长度定了，内容就定了）
//
// ============ 逐个看一遍，就明白它在数什么 ============
//
// P = a b a b a c
//
//   j=0  "a"           真前后缀只有空串 → match[0] = 0
//   j=1  "ab"          "a" != "b"              → 0
//   j=2  "aba"         "a" == "a"（前 a 后 a）  → 1
//   j=3  "abab"        "ab" == "ab"            → 2
//   j=4  "ababa"       "aba" == "aba"          → 3
//   j=5  "ababac"      前后缀怎么都对不上        → 0
//
// 所以 match = { 0, 0, 1, 2, 3, 0 }。
//
// ============ 它为什么能决定"滑多远" ============
//
// 假设在 P 的第 j 个字符处和主串失配了。这说明：
//
//     S[i .. i+j-1] == P[0 .. j-1]        ← 前面这 j 个字符已经确认相等
//
// 既然主串里这 j 个字符等于 P 的前 j 个字符，那么"P 的前 j 个字符的某个后缀"
// 同时也等于主串对应位置的内容。我们想让模式串尽量少往后挪，就要找一个
// **既是 P 的前缀、又是 P[0..j-1] 的后缀**的最长子串 —— 那正是 match[j-1]。
//
// 于是：失配时不需要把 j 清 0，只需要 j = match[j-1]。
// 主串指针 i 一动不动 —— 这就是 KMP 省下的那部分工作。
//
// ============ 一个容易记混的点 ============
//
// match[j] 描述的是 **P[0..j]** 这个前缀的**内部结构**，和主串无关。
// 它回答的问题是："P 自己前 j+1 个字符里，开头和结尾最多重叠多少个字符？"
// 想清楚这一点，buildMatch 的递推就不难理解了。

// match[j] = P[0..j] 的最长相等前后缀长度（真前后缀，不含整串）
// match[0] 恒为 0：长度 1 的串没有真前后缀
// "ababaca" 的 match 是 { 0, 0, 1, 2, 3, 0, 1 }

// 把 P[0..j] 的候选前后缀逐个列出来，直到找到最长的那一对
// 只依赖本模块：不需要 match 表，直接按定义硬算，"看得见的定义"才不容易记混
// 返回找到的最长长度；找不到返回 0
// 注意这里是最朴素的写法 O(j)，只为把定义讲清楚 —— 整表的 O(m) 算法在 04
int ShowMatchCalc(const char *P, int j)
{
    int k;

// 候选长度从大到小试：j 往下减到 1（真前后缀最长只能是 j）
    for (k = j; k >= 1; k--)
    {
        int t;
        int same = 1;

// 比"长度为 k 的前缀"和"长度为 k 的后缀"是否逐字符相等
        for (t = 0; t < k; t++)
        {
            if (P[t] != P[j - k + 1 + t])
            {
                same = 0;
                break;
            }
        }

// 第一个相等的 k 就是最长的，直接返回
        if (same) return k;
    }

// 连长度 1 都对不上，说明没有相等的真前后缀
    return 0;
}

// ============ 为什么能 O(m) 算出来 ============
//
// 有了 match[j-1]，match[j] 只有两种可能：
//
//   ① 如果 P[j] == P[match[j-1]]，那正好接上 → match[j] = match[j-1] + 1
//
//      P = a b a b ?        match[3] = 2（"ab"）
//          └─┘ └─┘         如果 ? == P[2] == 'a'，那 "aba" 也是前后缀 → 3
//
//   ② 如果 P[j] != P[match[j-1]]，就退一步看**次长**的相等前后缀。
//      次长是谁？正是 match[match[j-1] - 1] —— 对"最长的那一段"再求一次 match。
//
//      一直退到匹配上、或者退成 0 为止。退到 0 还不匹配，match[j] 就是 0。
//
// ============ 关键洞察：这个过程不回头 ============
//
// 看起来里面套了个 while 会退化，其实不会：因为 match[j] <= match[j-1] + 1，
// 而每次进 while 都让候选值至少减 1 —— 摊还下来整个循环是 O(m) 的。
//
// 一句话：外层循环往前走 j 一步，内层循环只把"已匹配的长度"往回退，
// 退的总次数不会超过前进的总步数。
//
// ============ 一个真实的例子，跟着走一遍 ============
//
// P = a b a b a c
//
//   j=1  P[1]='b' vs P[0]='a' 不等 → 退到 0 → match[1]=0
//   j=2  P[2]='a' vs P[0]='a' 相等 → match[2]=match[1]+1=1
//   j=3  P[3]='b' vs P[1]='b' 相等 → match[3]=match[2]+1=2
//   j=4  P[4]='a' vs P[2]='a' 相等 → match[4]=match[3]+1=3
//   j=5  P[5]='c' vs P[3]='b' 不等 → 退到 match[2]=1，再比 P[5] vs P[1]='b' 还不行
//        → 退到 match[0]=0，比 P[5] vs P[0]='a' 仍不行 → match[5]=0

// 就地填好调用者给的 match 数组（长度必须 >= m）
// match[0] = 0 是递推起点，从 j = 1 开始
// 失配时用 match[match[j-1]-1] 往后退，退到 0 为止
// 整体 O(m)：内层的回退总次数不超过外层的前进次数
void buildMatch(const char *P, int *match)
{
    int m = (int)strlen(P);
    int j;
    int k;

    if (m == 0) return;

// 长度为 1 的前缀没有真前后缀，起点固定是 0
    match[0] = 0;

    for (j = 1; j < m; j++)
    {
// k 表示"当前考虑的最长相等前后缀长度"，从上一格的结果开始试
        k = match[j - 1];

// 一直退到能接上（P[j] == P[k]）或者退无可退（k == 0）
        while (k > 0 && P[j] != P[k])
        {
// 次长的候选：对已经匹配的那一段再求一次它的匹配长度
            k = match[k - 1];
        }

// 能接上，长度加一
        if (P[j] == P[k])
        {
            match[j] = k + 1;
        }
        else
        {
// 退到 0 都对不上，说明没有任何真前后缀相等
            match[j] = 0;
        }
    }
}

// ============ 和暴力匹配逐行对照 ============
//
// 暴力匹配是双层 for，每次失败 i 往前挪一格、j 清 0。
// KMP 只有一个 while，i 和 j 各自只往前走：
//
//     while (i < n && j < m)
//         if (S[i] == P[j])  { i++; j++; }        ← 匹配，两个一起前进
//         else if (j > 0)      j = match[j-1];      ← 失配，只退 j，i 不动
//         else               i++;                  ← j 已经是 0，只能让 i 前进
//
// 三个分支都要有，缺一不可：
//
//   · 少了第三个分支，j == 0 且失配时会死循环（i 不前进、j 也不动）
//   · 少了第二个分支，就退化成暴力匹配
//
// ============ 复杂度为什么是 O(n + m) ============
//
// 看 i 和 j 的总变化量：
//   · i 只增不减，最多增 n 次
//   · j 每次匹配成功 +1，而失配分支让 j 至少减 1
//   · 所以 j 减少的总次数 <= j 增加的总次数 <= n
//
// 于是 while 的循环次数是 O(n)，加上预处理模式串的 O(m)，合计 **O(n + m)**。
// 注意这是**最坏情况**的保证 —— 暴力匹配的最坏情况是 O(n·m)。
//
// ============ 返回值约定 ============
//
// 返回模式串在主串里**第一次**出现的起始下标；找不到返回 -1。
// 循环结束时如果 j == m，说明整个模式串都匹配上了，
// 此时主串已经走到 i，匹配的起点就是 i - m。

// 失败函数（match 表）由 buildMatch 预先算好，传进来
// match 为 NULL 时先把模式串长度当 0 处理，避免解引用空指针
// 返回第一次出现的下标；找不到返回 -1
// 三个分支的顺序不能换：先比、再退 j、最后才动 i
int KMPMatch(const char *S, const char *P, const int *match)
{
    int n = (int)strlen(S);
    int m = (int)strlen(P);
    int i = 0;
    int j = 0;

// 空模式串约定和暴力匹配保持一致：返回 0
    if (m == 0) return 0;
// 没有 match 表就没法跳转，直接返回找不到（防御性写法）
    if (match == NULL) return -1;

// 两个指针都没走到各自末尾时继续
    while (i < n && j < m)
    {
// ① 当前字符相等：两个指针一起前进
        if (S[i] == P[j])
        {
            i++;
            j++;
        }
// ② 失配且 j > 0：主串指针不动，模式串往回滑到 match[j-1]
        else if (j > 0)
        {
            j = match[j - 1];
        }
// ③ 失配且 j == 0：模式串已经退无可退，只能让主串往前走一格
        else
        {
            i++;
        }
    }

// j 走到 m 说明模式串整体匹配上了，起点是 i - m
// 否则主串已扫完，返回 -1
    return (j == m) ? (i - m) : -1;
}

// ============ 为什么 main 里只做对照，不做讲解 ============
//
// 这一节的每一个知识点在 04、05 两个模块里已经讲完了。
// main 的职责只有一件：**把两个算法放在同一组输入上跑**，
// 让"结果一样、代价不同"这件事变成看得见的数字。
//
// 注意 main 模块里只允许有 main —— 辅助函数一律独立成模块，
// 否则练习模式里"只留 main"的脚手架会编不过。

// 场景一：P 在 S 里出现两次，两套算法都该返回 2
// 场景二：S 全是 a、P 以 c 结尾 —— 这是暴力匹配的最坏情况
// 场景三：P 在 S 中间，前面有一大段干扰字符
// 场景四：P 不在 S 里，两个算法都该返回 -1
// 每个场景都打印下标和 match 表，一眼能看出 match 表只依赖 P
int main(void)
{
    const char *S[4] = { "abababab", "aaaaaaaaab", "xxababacxx", "abcdef" };
    const char *P[4] = { "abab",     "aaab",       "ababac",     "xyz" };
    int match[64];
    int t;

    printf("暴力匹配 vs KMP —— 同一组输入，两个算法各跑一遍\n");
    printf("下标都从 0 开始\n\n");

    for (t = 0; t < 4; t++)
    {
        int n = (int)strlen(S[t]);
        int m = (int)strlen(P[t]);
        int naive, kmp;

        buildMatch(P[t], match);

        naive = NaiveMatch(S[t], P[t]);
        kmp = KMPMatch(S[t], P[t], match);

        printf("场景 %d：S = \"%s\"，P = \"%s\"\n", t + 1, S[t], P[t]);
        printf("  match 表（只看 P，和 S 无关）：");

        {
            int j;
            for (j = 0; j < m; j++)
            {
                printf(" %d", match[j]);
            }
        }

        printf("\n");
        printf("  NaiveMatch → %d\n", naive);
        printf("  KMPMatch   → %d\n", kmp);
        printf("  两者一致：%s\n\n", naive == kmp ? "是" : "否（有问题！）");
        (void)n;
    }

    printf("四个场景两个算法的结果必须完全一致 ——\n");
    printf("KMP 只是把「重复比较」省掉了，不会改变答案\n");

    return 0;
}

